const mouse={x:window.innerWidth/2,y:window.innerHeight/2};const cursorGlow=document.getElementById("cursorGlow");let cursorRaf=0;document.addEventListener("mousemove",(e)=>{mouse.x=e.clientX;mouse.y=e.clientY;if(!cursorRaf){cursorRaf=requestAnimationFrame(()=>{cursorGlow.style.transform=`translate(${mouse.x-150}px, ${mouse.y-150}px) translateZ(0)`;cursorRaf=0})}},{passive:true});